 if(!HzbFourMipBatchMatchesSequential3D(13,7)||!HzbFourMipBatchMatchesSequential3D(1919,1079)||!HzbFourMipBatchMatchesSequential3D(1,17)||!HzbHalfResolutionPhysicalMapping3D(1920,1080,6)||!HzbHalfResolutionPhysicalMapping3D(1919,1079,6)||HzbHalfResolutionResidentBytes3D(1920,1080,6,D3D12Renderer::BufferedFrames)>36u*1024u*1024u)return 19;
