  HzbScreenBounds3D{8,8,12,12,.2f,103,false},   // 自身深度
  HzbScreenBounds3D{-1,16,8,24,.7f,104,false}, // 畫面邊界
  HzbScreenBounds3D{16,16,24,24,.7f,105,true}, // 穿越 near plane
