 std::unordered_set<uint64_t> gold,hzb;uint64_t capture=1469598103934665603ull;
 for(const auto& candidate:candidates){if(reference.GoldOccluded(candidate))gold.insert(candidate.identity);if(reference.HzbOccluded(candidate)){hzb.insert(candidate.identity);capture=FoldHzbIdentity3D(capture,candidate.identity);}}
 for(uint64_t identity:hzb)if(!gold.contains(identity))return 1;
