 const HzbScreenBounds3D normalizedNegative{16,16,24,24,.7f,106,false};if(!reference.HzbOccluded(normalizedNegative))return 3;
 const bool cameraMoveFailOpen=HzbHistoryMustFailOpen3D(true,false,false,false,false,true); // 小幅移動使用 current-frame HZB，不需失效。
 if(cameraMoveFailOpen||!HzbHistoryMustFailOpen3D(true,false,false,false,true,true)||!HzbHistoryMustFailOpen3D(true,false,false,false,false,false))return 4;
 if(!HzbHistoryMustFailOpen3D(true,false,true,false,false,true)||!HzbHistoryMustFailOpen3D(true,false,false,true,false,true)||!HzbHistoryMustFailOpen3D(true,true,false,false,false,true)||!HzbHistoryMustFailOpen3D(false,false,false,false,false,true))return 5;
 // 多群組輸出必須保留原 submission identity，不可依可見順序重新編號。
 const std::array groups={uint64_t{7},uint64_t{3},uint64_t{7},uint64_t{9}};uint64_t groupHash=1469598103934665603ull;for(uint64_t group:groups)groupHash=FoldHzbIdentity3D(groupHash,group);
 const uint64_t expectedGroupHash=groupHash;if(groupHash!=expectedGroupHash||!capture)return 6;
